function SetupImportTools({rtl,kind,act,busy,onError}:{rtl:boolean;kind:"business_units"|"cost_centers";act:(action:string,extra:Row)=>Promise<Row|null>;busy:boolean;onError:(error:string)=>void}) {
  const columns=kind==="business_units"?["code","name_en","name_ar","is_active"]:["code","name_en","name_ar","description","is_active"];
  const template=()=>{
    const row=Object.fromEntries(columns.map(column=>[column,""]));
    const blob=new Blob(["\ufeff",payrollExcel([row],kind)],{type:"application/vnd.ms-excel;charset=utf-8"});
    const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`${kind}-template.xls`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  };
  const importFile=async(file:File)=>{
    try {
      if(file.size>2_000_000) throw new Error(words(rtl,"File exceeds 2 MB","الملف أكبر من ٢ ميجابايت"));
      const rows=readPayrollExcel(await file.text());
      if(!rows.length||rows.some(row=>columns.some(key=>!(key in row)))) throw new Error(words(rtl,"Use the supplied Excel template","استخدم قالب Excel المتاح"));
      await act(`import_${kind}`,{rows});
    } catch(cause) {onError(cause instanceof Error?cause.message:String(cause));}
  };
  return <div className="panel pr-panel pr-toolbar"><button className="outline" onClick={template}>{words(rtl,"Download Excel template","تنزيل قالب Excel")}</button><label className="pr-field"><span>{words(rtl,"Import Excel (.xls XML)","استيراد Excel (.xls XML)")}</span><input type="file" accept=".xls,.xml" disabled={busy} onChange={event=>{const file=event.target.files?.[0];if(file)void importFile(file);event.target.value="";}}/></label></div>;
}

function CostCenterBulk({rtl,rows,act,busy}:{rtl:boolean;rows:Row[];act:(action:string,extra:Row)=>Promise<Row|null>;busy:boolean}) {
  const [selected,setSelected]=useState<number[]>([]);
  const toggle=(id:number)=>setSelected(ids=>ids.includes(id)?ids.filter(item=>item!==id):[...ids,id]);
  return <div className="panel pr-panel"><h3>{words(rtl,"Bulk delete unused Cost Centers","حذف مراكز التكلفة غير المستخدمة")}</h3><div className="pr-scroll"><table><thead><tr><th>{words(rtl,"Select","تحديد")}</th><th>{words(rtl,"Code","الرمز")}</th><th>{words(rtl,"Name","الاسم")}</th></tr></thead><tbody>{rows.map(row=><tr key={s(row.id)}><td><input type="checkbox" checked={selected.includes(n(row.id))} onChange={()=>toggle(n(row.id))}/></td><td>{s(row.code)}</td><td>{s(rtl?(row.name_ar||row.name_en):(row.name_en||row.name_ar))}</td></tr>)}</tbody></table></div><button className="outline danger" disabled={busy||!selected.length} onClick={()=>{if(window.confirm(words(rtl,`Delete ${selected.length} unused Cost Centers?`,`حذف ${selected.length} من مراكز التكلفة غير المستخدمة؟`)))void act("bulk_delete_cost_centers",{ids:selected}).then(result=>{if(result)setSelected([]);});}}>{words(rtl,"Delete selected","حذف المحدد")}</button></div>;
}

function ElementAdvancedFields({rtl,element,setElement}:{rtl:boolean;element:Row;setElement:(next:Row)=>void}) {
  return <>{field(words(rtl,"Classification","التصنيف"),element.classification,value=>setElement({...element,classification:value}))}{field(words(rtl,"Formula","المعادلة"),element.formula,value=>setElement({...element,formula:value}))}{field(words(rtl,"Sort order","ترتيب العرض"),element.sortOrder,value=>setElement({...element,sortOrder:Number(value)}),"number")}{field(words(rtl,"GL account name","اسم حساب الأستاذ"),element.elementAccountName,value=>setElement({...element,elementAccountName:value}))}<label><input type="checkbox" checked={element.isActive!==false} onChange={event=>setElement({...element,isActive:event.target.checked})}/> {words(rtl,"Active","نشط")}</label></>;
}

function PayrollMatrix({rtl,data,year,month,busy,canEdit,listRows,act}:{rtl:boolean;data:Workspace;year:number;month:number;busy:boolean;canEdit:boolean;listRows:(rows:Row[])=>Row[];act:(action:string,extra:Row)=>Promise<Row|null>}) {
  const [changes,setChanges]=useState<Record<string,string>>({});
  const elements=data.elements.filter(row=>n(row.is_active)===1&&!n(row.is_basic_salary_element)&&!n(row.is_delay_minutes_element)&&!n(row.is_absence_element));
  const key=(employeeId:unknown,elementId:unknown)=>`${employeeId}:${elementId}`;
  const save=async()=>{
    const entries=Object.entries(changes).map(([cell,amount])=>{
      const [employeeId,elementId]=cell.split(":").map(Number);
      const existing=data.recurring.find(row=>n(row.employee_id)===employeeId&&n(row.element_id)===elementId);
      return {id:existing?.id,employeeId,elementId,amount:Number(amount),effectiveFrom:existing?.effective_from||`${year}-${String(month).padStart(2,"0")}-01`,effectiveTo:existing?.effective_to||null};
    });
    if(entries.some(row=>!Number.isFinite(row.amount)||row.amount<0))return;
    const result=await act("save_matrix_entries",{entries});if(result)setChanges({});
  };
  return <div className="panel pr-panel"><div className="pr-toolbar"><h2>{words(rtl,"Matrix Entry","الإدخال الجماعي")}</h2><button className="primary" disabled={busy||!canEdit||!Object.keys(changes).length} onClick={()=>void save()}>{words(rtl,"Save changed amounts","حفظ المبالغ المعدلة")} ({Object.keys(changes).length})</button></div><div className="pr-scroll"><table><thead><tr><th className="pr-sticky-name">{words(rtl,"Employee","الموظف")}</th>{elements.map(element=><th key={s(element.id)}>{s(rtl?(element.name_ar||element.name_en):(element.name_en||element.name_ar))}</th>)}</tr></thead><tbody>{listRows(data.employees).map(employee=><tr key={s(employee.id)}><th className="pr-sticky-name">{s(rtl?(employee.name_ar||employee.name_en):(employee.name_en||employee.name_ar))}</th>{elements.map(element=>{const cell=key(employee.id,element.id),existing=data.recurring.find(row=>n(row.employee_id)===n(employee.id)&&n(row.element_id)===n(element.id));return <td key={s(element.id)}><input aria-label={`${s(employee.employee_code)} ${s(element.code)}`} type="number" min="0" step="0.01" disabled={!canEdit||busy} value={changes[cell]??s(existing?.amount??"")} onChange={event=>setChanges(current=>({...current,[cell]:event.target.value}))}/><small>{s(employee.salary_currency||"SAR")}</small></td>;})}</tr>)}</tbody></table></div></div>;
}

function BusinessUnitSetup({rtl,data,act,busy,listRows}:{rtl:boolean;data:Workspace;act:(action:string,extra:Row)=>Promise<Row|null>;busy:boolean;listRows:(rows:Row[])=>Row[]}){
  const [unit,setUnit]=useState<Row>({code:"",nameEn:"",nameAr:""});
  const [assignment,setAssignment]=useState<Row>({employeeId:"",businessUnitId:""});
  const [report,setReport]=useState<Row[]>([]);
  const loadReport=useCallback(async()=>{try{const result=await call(null,"?view=business_unit_report") as {rows:Row[]};setReport(result.rows);}catch{/* The workspace error banner handles permission failures. */}},[]);
  useEffect(()=>{void loadReport();},[loadReport]);
  const exportReport=()=>{const rows=listRows(report).map(row=>({employee_code:row.employee_code,name_en:row.name_en,name_ar:row.name_ar,company:row.company_name,payroll_country:row.payroll_country,working_business_unit:row.business_unit_code||"",assignment_status:row.working_business_unit_id?"Assigned":"Missing"}));const blob=new Blob(["\ufeff",payrollExcel(rows,"Business Unit Mapping")],{type:"application/vnd.ms-excel;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="employee-business-unit-mapping.xls";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  return <div className="panel pr-panel"><h2>{words(rtl,"Business Units","وحدات الأعمال")}</h2><form className="pr-form" onSubmit={event=>{event.preventDefault();void act("save_business_unit",unit);}}>{field(words(rtl,"Code","الرمز"),unit.code,value=>setUnit({...unit,code:value}))}{field(words(rtl,"English name","الاسم الإنجليزي"),unit.nameEn,value=>setUnit({...unit,nameEn:value}))}{field(words(rtl,"Arabic name","الاسم العربي"),unit.nameAr,value=>setUnit({...unit,nameAr:value}))}<label><input type="checkbox" checked={unit.isActive!==false&&Number(unit.isActive??1)!==0} onChange={event=>setUnit({...unit,isActive:event.target.checked})}/> {words(rtl,"Active","نشط")}</label><button className="primary" disabled={busy}>{words(rtl,"Save","حفظ")}</button></form><div className="pr-scroll"><table><thead><tr><th>{words(rtl,"Code","الرمز")}</th><th>{words(rtl,"Name","الاسم")}</th><th>{words(rtl,"Status","الحالة")}</th><th/></tr></thead><tbody>{listRows(data.businessUnits).map(row=><tr key={s(row.id)}><td>{s(row.code)}</td><td>{s(rtl?(row.name_ar||row.name_en):(row.name_en||row.name_ar))}</td><td>{n(row.is_active)?words(rtl,"Active","نشط"):words(rtl,"Inactive","غير نشط")}</td><td><button className="outline" onClick={()=>setUnit({id:row.id,code:row.code,nameEn:row.name_en,nameAr:row.name_ar,isActive:row.is_active})}>{words(rtl,"Edit","تعديل")}</button><button className="outline danger" disabled={busy} onClick={()=>{if(window.confirm(words(rtl,"Delete this unused Business Unit?","حذف وحدة الأعمال غير المستخدمة؟")))void act("delete_business_unit",{id:row.id});}}>{words(rtl,"Delete","حذف")}</button></td></tr>)}</tbody></table></div><h3>{words(rtl,"Employee Working Business Unit","وحدة عمل الموظف")}</h3><button className="outline" onClick={exportReport}>{words(rtl,"Export employee mapping","تصدير ربط الموظفين")}</button><p>{words(rtl,"Missing assignments","التعيينات الناقصة")}: {report.filter(row=>!row.working_business_unit_id).length} / {report.length}</p><form className="pr-form" onSubmit={event=>{event.preventDefault();void act("assign_business_unit",assignment).then(()=>loadReport());}}><select value={s(assignment.employeeId)} onChange={event=>setAssignment({...assignment,employeeId:Number(event.target.value)})}><option value="">{words(rtl,"Employee","الموظف")}</option>{report.map(row=><option key={s(row.id)} value={s(row.id)}>{s(row.employee_code)} · {s(rtl?(row.name_ar||row.name_en):(row.name_en||row.name_ar))}</option>)}</select><select value={s(assignment.businessUnitId)} onChange={event=>setAssignment({...assignment,businessUnitId:Number(event.target.value)})}><option value="">{words(rtl,"Business unit","وحدة الأعمال")}</option>{data.businessUnits.map(row=><option key={s(row.id)} value={s(row.id)}>{s(row.name_en)}</option>)}</select><button className="primary" disabled={busy}>{words(rtl,"Assign","تعيين")}</button></form><div className="pr-scroll"><table><thead><tr><th>{words(rtl,"Employee","الموظف")}</th><th>{words(rtl,"Company","الشركة")}</th><th>{words(rtl,"Current Business Unit","وحدة العمل الحالية")}</th><th>{words(rtl,"Status","الحالة")}</th><th/></tr></thead><tbody>{listRows(report).map(row=><tr key={s(row.id)}><td>{s(row.employee_code)} · {s(rtl?(row.name_ar||row.name_en):(row.name_en||row.name_ar))}</td><td>{s(row.company_name)}</td><td>{s(row.business_unit_code)||"—"}</td><td>{row.working_business_unit_id?words(rtl,"Assigned","معيّن"):words(rtl,"Missing","ناقص")}</td><td><button className="outline" onClick={()=>setAssignment({employeeId:row.id,businessUnitId:row.working_business_unit_id||""})}>{words(rtl,"Assign","تعيين")}</button></td></tr>)}</tbody></table></div></div>;
}

function PayrollSetupExtras({rtl,data,act,busy,mode,listRows}:{rtl:boolean;data:Workspace;act:(action:string,extra:Row)=>Promise<Row|null>;busy:boolean;mode:string;listRows:(rows:Row[])=>Row[]}) {
  const [cost,setCost]=useState<Row>({code:"",nameEn:"",nameAr:"",description:""});
  const [mapping,setMapping]=useState<Row>({businessUnitId:"",costCenterId:"",payrollDrAccount:""});
  const label=(row:Row)=>s(rtl?(row.name_ar||row.name_en):(row.name_en||row.name_ar));
  return <div className="panel pr-panel"><h2>{words(rtl,"Cost Centers and Business Unit Mapping","مراكز التكلفة وربط وحدات الأعمال")}</h2>
    {mode==="cost_centers"&&<><form className="pr-form" onSubmit={event=>{event.preventDefault();void act("save_cost_center",cost);}}>{field(words(rtl,"Cost center code","رمز مركز التكلفة"),cost.code,value=>setCost({...cost,code:value}))}{field(words(rtl,"English name","الاسم الإنجليزي"),cost.nameEn,value=>setCost({...cost,nameEn:value}))}{field(words(rtl,"Arabic name","الاسم العربي"),cost.nameAr,value=>setCost({...cost,nameAr:value}))}{field(words(rtl,"Description","الوصف"),cost.description,value=>setCost({...cost,description:value}))}<label><input type="checkbox" checked={cost.isActive!==false} onChange={event=>setCost({...cost,isActive:event.target.checked})}/> {words(rtl,"Active","نشط")}</label><button className="primary" disabled={busy}>{words(rtl,"Save Cost Center","حفظ مركز التكلفة")}</button></form><div className="pr-scroll"><table><tbody>{listRows(data.costCenters).map(row=><tr key={s(row.id)}><td>{s(row.code)}</td><td>{label(row)}</td><td>{s(row.status)}</td><td><button className="outline" onClick={()=>setCost({id:row.id,code:row.code,nameEn:row.name_en,nameAr:row.name_ar,description:row.description,isActive:row.status==="active"})}>{words(rtl,"Edit","تعديل")}</button></td></tr>)}</tbody></table></div></>}
    {mode==="mapping"&&<><form className="pr-form" onSubmit={event=>{event.preventDefault();void act("save_mapping",mapping);}}><select value={s(mapping.businessUnitId)} onChange={event=>setMapping({...mapping,businessUnitId:Number(event.target.value)})}><option value="">{words(rtl,"Business unit","وحدة الأعمال")}</option>{data.businessUnits.map(row=><option key={s(row.id)} value={s(row.id)}>{label(row)}</option>)}</select><select value={s(mapping.costCenterId)} onChange={event=>setMapping({...mapping,costCenterId:Number(event.target.value)})}><option value="">{words(rtl,"Cost center","مركز التكلفة")}</option>{data.costCenters.map(row=><option key={s(row.id)} value={s(row.id)}>{label(row)}</option>)}</select>{field(words(rtl,"Payroll debit account","حساب الخصم للرواتب"),mapping.payrollDrAccount,value=>setMapping({...mapping,payrollDrAccount:value}))}<button className="primary" disabled={busy}>{words(rtl,"Save Mapping","حفظ الربط")}</button></form><div className="pr-scroll"><table><tbody>{listRows(data.mappings).map(row=><tr key={s(row.id)}><td>{label(data.businessUnits.find(unit=>n(unit.id)===n(row.business_unit_id))||{})}</td><td>{label(data.costCenters.find(center=>n(center.id)===n(row.cost_center_id))||{})}</td><td>{s(row.payroll_dr_account)}</td><td><button className="outline" onClick={()=>setMapping({businessUnitId:row.business_unit_id,costCenterId:row.cost_center_id,payrollDrAccount:row.payroll_dr_account})}>{words(rtl,"Edit","تعديل")}</button></td></tr>)}</tbody></table></div></>}
  </div>;
}


